import React from 'react';
import { Project } from '@/types';

interface ProjectCardProps {
  project: Project;
  onOpen: (project: Project) => void;
}

export default function ProjectCard({ project, onOpen }: ProjectCardProps) {
  const bgStyle = project.backgroundImage
    ? {
        backgroundImage: `url('${project.backgroundImage}')`,
        backgroundPosition: 'center',
        backgroundSize: 'cover',
        backgroundRepeat: 'no-repeat',
      }
    : {};

  const bgClass = project.type === 'hackathon' 
    ? project.backgroundImage
      ? 'h-full min-h-[160px] rounded-lg p-6 transition-all duration-300 hover:shadow-lg cursor-pointer text-left relative overflow-hidden bg-cover bg-center flex flex-col'
      : 'h-full min-h-[160px] bg-white rounded-lg p-6 transition-all duration-300 hover:shadow-lg cursor-pointer text-left relative overflow-hidden flex flex-col'
    : project.backgroundImage
      ? 'h-full min-h-[160px] rounded-lg p-6 transition-all duration-300 hover:shadow-lg cursor-pointer text-left w-full md:w-1/2 mx-auto block relative overflow-hidden bg-cover bg-center flex flex-col'
      : 'h-full min-h-[160px] bg-gray-800 hover:bg-gray-900 rounded-lg p-6 transition-all duration-300 hover:shadow-lg cursor-pointer text-left w-full md:w-1/2 mx-auto block relative flex flex-col';

  const tagColor = project.type === 'hackathon' 
    ? 'bg-blue-100 text-blue-800'
    : 'bg-green-100 text-green-800';

  return (
    <button onClick={() => onOpen(project)} className={bgClass} style={bgStyle}>
      {project.backgroundImage && (
        <div className="absolute inset-0 bg-black/40 hover:bg-black/50 transition-colors"></div>
      )}
      <span className={`absolute top-3 right-3 text-xs ${tagColor} px-2 py-1 rounded font-semibold z-10`}>
        {project.type === 'hackathon' ? 'Hackathon' : 'Personal Project'}
      </span>
      <div className={`relative z-10 flex-1 flex flex-col ${project.backgroundImage ? '' : ''}`}>
        <h3 className={`text-xl font-bold mb-2 pr-16 ${project.backgroundImage ? 'text-white drop-shadow-lg' : project.type === 'hackathon' ? 'text-gray-900' : 'text-white'}`}>
          {project.shortTitle}
        </h3>
        {project.metadata.place && (
          <p className={`${project.backgroundImage ? 'text-white drop-shadow-md' : project.type === 'hackathon' ? 'text-gray-700' : 'text-gray-300'} mb-2`}>
            {project.metadata.place}
          </p>
        )}
        {project.metadata.earnings && (
          <p className={`${project.backgroundImage ? 'text-white font-semibold drop-shadow-md' : project.type === 'hackathon' ? 'text-gray-800 font-semibold' : 'text-gray-200'} text-sm mt-1`}>
            💰 {project.metadata.earnings}
          </p>
        )}
      </div>
    </button>
  );
}

