import React from 'react';
import { ProjectSection, FeatureItem, TechStackItem } from '@/types';

export const createSectionHeader = (
  title: string,
  gradient: string = 'from-blue-500 to-purple-500'
): React.ReactNode => (
  <h4 className="text-2xl font-bold text-gray-900 flex items-center gap-2">
    <span className={`w-1 h-6 bg-gradient-to-b ${gradient} rounded-full`}></span>
    {title}
  </h4>
);

export const createFeatureList = (features: FeatureItem[]): React.ReactNode => (
  <div className="bg-gray-50 rounded-xl p-6 border border-gray-100">
    <div className="grid md:grid-cols-2 gap-3">
      {features.map((feature, index) => (
        <div key={index} className="flex items-start gap-3">
          <div
            className={`w-2 h-2 rounded-full ${feature.color || 'bg-blue-500'} mt-2 flex-shrink-0`}
          ></div>
          <div>
            <strong className="text-gray-900">{feature.title}:</strong>
            <span className="text-gray-700"> {feature.description}</span>
          </div>
        </div>
      ))}
    </div>
  </div>
);

export const createTechStack = (techItems: TechStackItem[]): React.ReactNode => (
  <div className="grid md:grid-cols-2 gap-3">
    {techItems.map((item, index) => (
      <div key={index} className="flex items-center gap-3 bg-white rounded-lg p-3 border border-gray-200">
        <div className={`w-2 h-2 rounded-full ${item.color || 'bg-indigo-500'}`}></div>
        <div>
          <strong className="text-gray-900">{item.category}:</strong>
          <span className="text-gray-700"> {item.technology}</span>
        </div>
      </div>
    ))}
  </div>
);

export const createHighlightedSection = (
  title: string,
  content: React.ReactNode,
  gradient: string = 'from-blue-500 to-cyan-500',
  bgColor: string = 'bg-blue-50',
  borderColor: string = 'border-blue-100'
): React.ReactNode => (
  <div className={`space-y-3 ${bgColor} rounded-xl p-6 border ${borderColor}`}>
    {createSectionHeader(title, gradient)}
    {content}
  </div>
);

export const createProjectHeader = (
  title: string,
  tags: Array<{ label: string; color?: string }>,
  description: string
): React.ReactNode => (
  <div className="border-b border-gray-200 pb-6">
    <h4 className="text-3xl font-bold text-gray-900 mb-3 bg-gradient-to-r from-gray-900 to-gray-700 bg-clip-text text-transparent">
      {title}
    </h4>
    <div className="flex flex-wrap gap-2 text-sm text-gray-600 mb-3">
      {tags.map((tag, index) => (
        <span
          key={index}
          className={`${tag.color || 'bg-blue-100 text-blue-800'} px-2 py-1 rounded font-semibold`}
        >
          {tag.label}
        </span>
      ))}
    </div>
    <p className="text-lg text-gray-600 leading-relaxed">{description}</p>
  </div>
);

